export class Writer{constructor(){this.parts=[];this.length=0;}bytes(v){const a=v instanceof Uint8Array?v:new Uint8Array(v);this.parts.push(a);this.length+=a.length;return this;}num(type,v){const a=new Uint8Array({u8:1,u16:2,i32:4,u32:4,f32:4}[type]);const d=new DataView(a.buffer);const f={u8:'setUint8',u16:'setUint16',i32:'setInt32',u32:'setUint32',f32:'setFloat32'}[type];d[f](0,v,true);return this.bytes(a);}u8(v){return this.num('u8',v);}u16(v){return this.num('u16',v);}i32(v){return this.num('i32',v);}u32(v){return this.num('u32',v);}f(v){return this.num('f32',v);}vec(v){v.forEach(x=>this.f(x));return this;}text(s){const a=new Uint8Array(s.length*2),d=new DataView(a.buffer);for(let i=0;i<s.length;i++)d.setUint16(i*2,s.charCodeAt(i),true);return this.i32(a.length).bytes(a);}finish(){const all=new Uint8Array(this.length);let at=0;for(const p of this.parts){all.set(p,at);at+=p.length;}return all;}}
export function exportPMX(avatar,state){const model=collectModel(avatar);const w=new Writer();w.bytes(new TextEncoder().encode('PMX ')).f(2).u8(8).bytes([0,0,4,4,4,4,4,4]);w.text(state.name).text(state.name).text('Pixel Pals에서 직접 제작한 로우폴리 캐릭터. 표준 MMD 본과 다리 IK 포함.').text('Original Pixel Pals character. Rigid low-poly skinning; standard MMD bones and leg IK.');const mirror=v=>[v[0]*8,v[1]*8,-v[2]*8];const n=model.vertices.length/3;w.i32(n);for(let i=0;i<n;i++){w.vec(mirror(model.vertices.slice(i*3,i*3+3)));const norm=model.normals.slice(i*3,i*3+3);w.vec([norm[0],norm[1],-norm[2]]).vec([model.uvs[i*2],1-model.uvs[i*2+1]]);const w0=model.skinWeights[i*4],w1=model.skinWeights[i*4+1];if(model.skinWeights[i*4+2]>0||model.skinWeights[i*4+3]>0){w.u8(2);model.skinIndices.slice(i*4,i*4+4).forEach(b=>w.i32(b));w.vec(model.skinWeights.slice(i*4,i*4+4));}else if(w1>0)w.u8(1).i32(model.skinIndices[i*4]).i32(model.skinIndices[i*4+1]).f(w0);else w.u8(0).i32(model.skinIndices[i*4]);w.f(1);}w.i32(model.indices.length);for(let i=0;i<model.indices.length;i+=3)w.i32(model.indices[i]).i32(model.indices[i+2]).i32(model.indices[i+1]);const maps=[...new Set(model.materials.map(m=>m.map).filter(Boolean))],textures=maps.map((texture,i)=>({texture,name:i===0?'face.png':`texture-${i+1}.png`}));w.i32(textures.length);textures.forEach(t=>w.text(t.name));w.i32(model.materials.length);model.materials.forEach((m,i)=>{const c=m.color.clone().convertLinearToSRGB(),edge=new T.Color(state.outlineColor).convertLinearToSRGB();w.text(m.map?'顔':`Material ${i}`).text(m.map?'Pixel face':`Material ${i}`).vec([c.r,c.g,c.b,m.opacity]).vec([.04,.04,.04]).f(1).vec([c.r*.4,c.g*.4,c.b*.4]).u8(15|(state.outline?16:0)).vec([edge.r,edge.g,edge.b,1]).f(state.outline?state.outlineWidth*8:0).i32(m.map?maps.indexOf(m.map):-1).i32(-1).u8(0).u8(1).u8(0).text('').i32(model.ranges[i].count);});w.i32(boneDefs.length);boneDefs.forEach(([jp,en,parent],i)=>{const ik=i===20||i===21;const movable=i<3||ik;const flags=0x1a|(movable?4:0)|(ik?0x20:0);w.text(jp).text(en).vec(mirror(model.bonePositions[i])).i32(parent).i32(ik?1:0).u16(flags).vec([0,i===5?2:1,0]);if(ik){const ankle=i===20?16:19,knee=ankle-1,leg=ankle-2;w.i32(ankle).i32(40).f(.5).i32(2).i32(knee).u8(1).vec([-Math.PI,0,0]).vec([-.001,0,0]).i32(leg).u8(0);}});w.i32(0);w.i32(2).text('Root').text('Root').u8(1).i32(1).u8(0).i32(0).text('体').text('Body').u8(0).i32(boneDefs.length-1);for(let i=1;i<boneDefs.length;i++)w.u8(0).i32(i);w.i32(0).i32(0);return{bytes:w.finish(),model,textures};}

class Reader{constructor(buffer){this.d=new DataView(buffer);this.at=0;}need(n){if(this.at+n>this.d.byteLength)throw new Error('파일 데이터가 중간에 끊어졌습니다.');}u32(){this.need(4);const v=this.d.getUint32(this.at,true);this.at+=4;return v;}f(){this.need(4);const v=this.d.getFloat32(this.at,true);this.at+=4;if(!Number.isFinite(v))throw new Error('모션 좌표가 올바르지 않습니다.');return v;}str(n){this.need(n);const b=new Uint8Array(this.d.buffer,this.at,n);this.at+=n;return new TextDecoder('shift-jis').decode(b.subarray(0,b.indexOf(0)<0?n:b.indexOf(0)));}skip(n){this.need(n);this.at+=n;}}
export function parseVMD(buffer){const r=new Reader(buffer);const sig=r.str(30);if(!sig.startsWith('Vocaloid Motion Data'))throw new Error('올바른 VMD 모션 파일이 아닙니다.');const modelName=r.str(sig.includes('0002')?20:10);const count=r.u32();if(count>500000||count*111>r.d.byteLength-r.at)throw new Error('VMD 키프레임 데이터가 올바르지 않습니다.');const tracks=new Map();let lastFrame=0;for(let i=0;i<count;i++){const name=r.str(15),frame=r.u32(),position=[r.f(),r.f(),r.f()],rotation=[r.f(),r.f(),r.f(),r.f()];r.need(64);const interpolation=Array.from(new Uint8Array(buffer,r.at,16));r.skip(64);if(rotation.every(v=>v===0))throw new Error('VMD 회전 정보가 올바르지 않습니다.');if(!tracks.has(name))tracks.set(name,[]);tracks.get(name).push({frame,position,rotation,interpolation});lastFrame=Math.max(lastFrame,frame);}if(count===0)throw new Error('이 파일에는 캐릭터 본 모션이 없습니다.');tracks.forEach(keys=>keys.sort((a,b)=>a.frame-b.frame));return{tracks,duration:Math.max(lastFrame/30,1/30),modelName};}
function bezier(u,ip,channel){const x1=ip[channel]/127,y1=ip[channel+4]/127,x2=ip[channel+8]/127,y2=ip[channel+12]/127;if(![x1,y1,x2,y2].every(x=>x>=0&&x<=1))return u;let lo=0,hi=1,z=u;for(let i=0;i<12;i++){z=(lo+hi)/2;const x=3*(1-z)*(1-z)*z*x1+3*(1-z)*z*z*x2+z*z*z;if(x<u)lo=z;else hi=z;}return 3*(1-z)*(1-z)*z*y1+3*(1-z)*z*z*y2+z*z*z;}
const aliases={'左足IK':'左足ＩＫ','右足IK':'右足ＩＫ','グルーブ':'センター','上半身2':'上半身'};
export function vmdMapping(vmd){const matches=[];for(const [name,keys]of vmd.tracks){const i=boneDefs.findIndex(b=>b[0]===(aliases[name]??name)||b[1]===name);if(i>=0)matches.push({i,name,keys});}return matches;}
export function applyVMD(avatar,mapped,time){resetPose(avatar);const frame=time*30;for(const {i,keys}of mapped){let lo=0,hi=keys.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(keys[mid].frame<=frame)lo=mid;else hi=mid-1;}const a=keys[lo],b=keys[Math.min(lo+1,keys.length-1)];const u=a===b?0:T.MathUtils.clamp((frame-a.frame)/(b.frame-a.frame),0,1);const qa=new T.Quaternion(-a.rotation[0],-a.rotation[1],a.rotation[2],a.rotation[3]).normalize(),qb=new T.Quaternion(-b.rotation[0],-b.rotation[1],b.rotation[2],b.rotation[3]).normalize();avatar.bones[i].quaternion.copy(avatar.bones[i].userData.restQuaternion).multiply(qa.slerp(qb,bezier(u,b.interpolation,3)));if(i<3){for(let c=0;c<3;c++){const v=T.MathUtils.lerp(a.position[c],b.position[c],bezier(u,b.interpolation,c))/8*(c===2?-1:1);avatar.bones[i].position.setComponent(c,avatar.bones[i].position.getComponent(c)+v);}}}
 // Two-bone leg IK places the feet when a VMD uses standard foot IK targets.
 avatar.root.updateMatrixWorld(true);for(const [ik,upper,knee,ankle]of [[20,14,15,16],[21,17,18,19]]){const track=mapped.find(x=>x.i===ik);if(!track)continue;const keys=track.keys;let j=0;while(j+1<keys.length&&keys[j+1].frame<=frame)j++;const a=keys[j],b=keys[Math.min(j+1,keys.length-1)],u=a===b?0:T.MathUtils.clamp((frame-a.frame)/(b.frame-a.frame),0,1);const target=avatar.bones[ik].getWorldPosition(new T.Vector3());target.add(new T.Vector3(T.MathUtils.lerp(a.position[0],b.position[0],u)/8,T.MathUtils.lerp(a.position[1],b.position[1],u)/8,-T.MathUtils.lerp(a.position[2],b.position[2],u)/8));for(let iter=0;iter<7;iter++)for(const jointIndex of[knee,upper]){const joint=avatar.bones[jointIndex];const inv=joint.getWorldQuaternion(new T.Quaternion()).invert();const jp=joint.getWorldPosition(new T.Vector3());const from=avatar.bones[ankle].getWorldPosition(new T.Vector3()).sub(jp).applyQuaternion(inv).normalize();const to=target.clone().sub(jp).applyQuaternion(inv).normalize();if(from.lengthSq()&&to.lengthSq())joint.quaternion.multiply(new T.Quaternion().setFromUnitVectors(from,to));avatar.root.updateMatrixWorld(true);}}
}
export function validateState(value,base){if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('캐릭터 설정이 올바르지 않습니다.');const s={...base};const numbers=numberRules,enums=enumRules;for(const [k,v]of Object.entries(value)){if(!(k in base))continue;if(k in numbers){if(typeof v!=='number'||!Number.isFinite(v)||v<numbers[k][0]||v>numbers[k][1])throw new Error(`${k} 값이 범위를 벗어났습니다.`);s[k]=v;}else if(k in enums){if(!enums[k].includes(v))throw new Error(`${k} 옵션을 사용할 수 없습니다.`);s[k]=v;}else if(k==='backgroundImage'){if(!validBackgroundData(v))throw new Error('배경 사진 데이터가 올바르지 않습니다.');s[k]=v;}else if(k==='backgroundImageName'){if(typeof v!=='string'||v.length>120)throw new Error('배경 사진 이름이 올바르지 않습니다.');s[k]=v;}else if(k==='accessoryTransforms'){s[k]=validateAccessoryTransforms(v);}else if(k==='faceDecorations'){if(!Array.isArray(v)||v.some(x=>x==='none'||!enumRules.faceDeco.includes(x))||new Set(v).size!==v.length)throw new Error('얼굴 장식 선택이 올바르지 않습니다.');s[k]=[...v];}else if(k==='dots'||k==='scars'){if(!Array.isArray(v))throw new Error('장식 목록이 올바르지 않습니다.');s[k]=v.map(d=>{if(!d||typeof d!=='object'||!/^#[0-9a-f]{6}$/i.test(d.color))throw new Error('장식 색상이 올바르지 않습니다.');for(const[n,min,max]of[['x',0,1],['y',0,1],['size',.005,.4]])if(typeof d[n]!=='number'||!Number.isFinite(d[n])||d[n]<min||d[n]>max)throw new Error('장식 위치와 크기가 올바르지 않습니다.');if(k==='scars'&&(!['line','stitch','cross','double'].includes(d.type)||typeof d.angle!=='number'||!Number.isFinite(d.angle)||Math.abs(d.angle)>180))throw new Error('흉터 모양이 올바르지 않습니다.');if(k==='scars')for(const field of['width','height'])if(d[field]!==undefined&&(typeof d[field]!=='number'||!Number.isFinite(d[field])||d[field]<.1||d[field]>3))throw new Error('흉터 비율이 올바르지 않습니다.');return k==='scars'?{...d,width:d.width??1,height:d.height??1}:{...d};});}else if(k.endsWith('Color')){if(typeof v!=='string'||!/^#[0-9a-f]{6}$/i.test(v))throw new Error('색상 값이 올바르지 않습니다.');s[k]=v;}else if(k==='name'){if(typeof v!=='string'||v.length>36)throw new Error('이름은 36자 이내로 입력해 주세요.');s.name=v||'친구';}else{if(typeof v!=='boolean')throw new Error(`${k} 설정이 올바르지 않습니다.`);s[k]=v;}}if(Object.hasOwn(value,'faceDecorations'))s.faceDeco=s.faceDecorations[0]??'none';else if(Object.hasOwn(value,'faceDeco'))s.faceDecorations=s.faceDeco==='none'?[]:[s.faceDeco];return s;}
